<?php
require_once __DIR__.'/backend/authorization.php';require_once __DIR__.'/backend/db.php';requireRegularAdmin();
$today=date('Y-m-d');
function countQuery(mysqli $conn,string $sql):int{return (int)$conn->query($sql)->fetch_assoc()['total'];}
$totalToday=countQuery($conn,"SELECT COUNT(*) total FROM bookings WHERE booking_date=CURDATE()");
$pending=countQuery($conn,"SELECT COUNT(*) total FROM bookings WHERE status='Pending'");
$approvedToday=countQuery($conn,"SELECT COUNT(*) total FROM bookings WHERE booking_date=CURDATE() AND status='Approved'");
$checkedIn=countQuery($conn,"SELECT COUNT(*) total FROM bookings WHERE booking_date=CURDATE() AND status='Checked-in'");
$completedToday=countQuery($conn,"SELECT COUNT(*) total FROM bookings WHERE booking_date=CURDATE() AND status='Completed'");
$unpaid=countQuery($conn,"SELECT COUNT(*) total FROM bookings WHERE status IN ('Approved','Checked-in','Completed') AND payment_status<>'Paid'");
$customers=countQuery($conn,"SELECT COUNT(*) total FROM users WHERE role='user' AND account_status='active'");
$upcoming=$conn->query("SELECT id,full_name,service_type,booking_date,booking_time,status,payment_status FROM bookings WHERE booking_date>=CURDATE() AND status IN ('Pending','Approved','Checked-in') ORDER BY booking_date,booking_time LIMIT 8");
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Front Desk Dashboard | Oh My Gracious</title><link rel="stylesheet" href="css/style.css"></head><body><header class="navbar"><div class="logo">Front Desk</div><nav><a class="active" href="admin-dashboard.php">Dashboard</a><a href="admin-bookings.php">Appointments</a><a href="admin-create-booking.php">Create Booking</a><a href="availability-management.php">Availability</a><a href="customers.php">Customers</a><a href="logout.php" class="logout-btn">Logout</a></nav></header><main class="page-wrap"><div class="page-heading"><div><p class="eyebrow">RECEPTIONIST / FRONT DESK</p><h1>Good day, <?=h($_SESSION['full_name'])?></h1><p>Manage customer flow and appointments without access to owner-only financial settings.</p></div><div class="button-row"><a class="btn primary" href="admin-create-booking.php">Create Booking</a><a class="btn ghost" href="admin-bookings.php">Manage Appointments</a><a class="btn ghost" href="availability-management.php">Manage Availability</a></div></div><div class="stat-grid"><div class="stat-card"><span>Today's Appointments</span><strong><?=$totalToday?></strong></div><div class="stat-card"><span>Pending Requests</span><strong><?=$pending?></strong></div><div class="stat-card"><span>Approved Today</span><strong><?=$approvedToday?></strong></div><div class="stat-card"><span>Checked In</span><strong><?=$checkedIn?></strong></div><div class="stat-card"><span>Completed Today</span><strong><?=$completedToday?></strong></div><div class="stat-card warning"><span>Needs Payment Action</span><strong><?=$unpaid?></strong></div><div class="stat-card"><span>Active Customers</span><strong><?=$customers?></strong></div></div><section class="panel"><div class="section-heading"><div><h2>Upcoming Queue</h2><p>Next customer requests and approved appointments.</p></div><a href="admin-bookings.php">View all</a></div><div class="table-scroll"><table><thead><tr><th>Customer</th><th>Services</th><th>Date</th><th>Time</th><th>Status</th><th>Payment</th></tr></thead><tbody><?php if(!$upcoming->num_rows):?><tr><td colspan="6" class="empty-cell">No upcoming appointments.</td></tr><?php endif;?><?php while($b=$upcoming->fetch_assoc()):?><tr><td><?=h($b['full_name'])?></td><td><?=h($b['service_type'])?></td><td><?=h(date('M j, Y',strtotime($b['booking_date'])))?></td><td><?=h(date('g:i A',strtotime($b['booking_time'])))?></td><td><span class="status neutral"><?=h($b['status'])?></span></td><td><span class="status neutral"><?=h($b['payment_status'])?></span></td></tr><?php endwhile;?></tbody></table></div></section></main></body></html>
